const dutySteps = (thing: string, absolute: [string, string], removable: [string, string], blessing: [string, string]): DutyCase["steps"] => [
  {
    id: "absolute", label: "Absolute trial?", chapterId: 29,
    question: `Is ${thing} itself unbelief, a disobedience, or a trait of bad character?`,
    yes: absolute[0], no: absolute[1],
  },
  {
    id: "removable", label: "Within your power?", chapterId: 29,
    question: `Is removing ${thing} actually within your power?`,
    yes: removable[0], no: removable[1],
  },
  {
    id: "blessing", label: "A blessing in some aspect?", chapterId: 19,
    question: `Is there an aspect in which ${thing} is a blessing to you?`,
    yes: blessing[0], no: blessing[1],
  },
];

const dutyVerdicts = (leave: string, remove: string, patience: string, both: string): DutyCase["verdicts"] => [
  { id: "leave", name: "Leave it, do not endure it", body: leave, action: "Endurance is the wrong response here. Ghazali is explicit that the unbeliever is not commanded to be patient over his unbelief but to leave it, and the sinner not to endure his sin but to leave it.", chapterId: 29 },
  { id: "remove", name: "Remove it", body: remove, action: "You are commanded to remove the pain rather than to bear it. The thirsty man who lets his pain grow is told to drink, not to endure.", chapterId: 29 },
  { id: "patience", name: "Patience", body: patience, action: "The pain is not yours to remove, so the duty is the steadiness already defined: hold the religious motive against the pull, and strengthen it by working at certainty.", chapterId: 2 },
  { id: "both", name: "Patience and gratitude together", body: both, action: "Both duties fall on this at once. Endure the aspect in which it is a trial and use rightly the aspect in which it is a blessing; on Ghazali's account this is the ordinary case, not the exception.", chapterId: 29 },
];

